 *   hours: 7,
 *   minutes: 5,
 *   seconds: 0
 * })
 * //=> 'P39Y2M20DT0H0M0S'
 */
export function formatISODuration(
  duration: Duration,
  options?: FormatISODurationOptions,
): string {
  const omitZeroUnits = options?.omitZeroUnits;

  if (omitZeroUnits !== undefined && typeof omitZeroUnits !== "boolean") {
    throw new RangeError("omitZeroUnits must be a boolean");
  }

  const {
    years = 0,
    months = 0,
    days = 0,
    hours = 0,
    minutes = 0,
    seconds = 0,
  } = duration;

  if (!omitZeroUnits) {
    return `P${years}Y${months}M${days}DT${hours}H${minutes}M${seconds}S`;
  }

  const date = [
    years !== 0 ? `${years}Y` : "",
    months !== 0 ? `${months}M` : "",
    days !== 0 ? `${days}D` : "",
  ].join("");
  const time = [
    hours !== 0 ? `${hours}H` : "",
    minutes !== 0 ? `${minutes}M` : "",
    seconds !== 0 ? `${seconds}S` : "",
  ].join("");

  if (!date && !time) return "PT0S";
  return `P${date}${time ? `T${time}` : ""}`;
}

