export interface EachDayOfIntervalOptions<DateType extends Date = Date>
  extends StepOptions,
    ContextOptions<DateType> {
  /** The maximum number of dates to return */
  maxDates?: number;
}

{
  const maxDates = options?.maxDates;
  if (
    maxDates !== undefined &&
    (!Number.isFinite(maxDates) || !Number.isInteger(maxDates) || maxDates < 0)
  ) {
    throw new RangeError("options.maxDates must be a finite nonnegative integer");
  }

  const { start, end } = normalizeInterval(options?.in, interval);

  let reversed = +start > +end;
  const endTime = reversed ? +start : +end;
  const date = reversed ? end : start;
  date.setHours(0, 0, 0, 0);

  let step = options?.step ?? 1;
  if (!step || maxDates === 0) return [];
  if (step < 0) {
    step = -step;
    reversed = !reversed;
  }

  const dates: EachDayOfIntervalResult<IntervalType, Options> = [];
  let datesStart = 0;

  while (+date <= endTime) {
    const dateToAdd = constructFrom(start, date);

    if (maxDates !== undefined && reversed) {
      if (dates.length < maxDates) {
        dates.push(dateToAdd);
      } else {
        dates[datesStart] = dateToAdd;
        datesStart = (datesStart + 1) % maxDates;
      }
    } else {
      dates.push(dateToAdd);
      if (maxDates !== undefined && dates.length === maxDates) break;
    }

    date.setDate(date.getDate() + step);
    date.setHours(0, 0, 0, 0);
  }

  if (datesStart) {
    dates.push(...dates.splice(0, datesStart));
  }

  return reversed ? dates.reverse() : dates;
}

