export interface EachDayOfIntervalOptions<DateType extends Date = Date>
  extends StepOptions,
    ContextOptions<DateType> {
  /** The maximum number of dates to return. */
  maxDates?: number;
}

{
  const maxDates = options?.maxDates;
  if (
    maxDates !== undefined &&
    (!Number.isFinite(maxDates) ||
      !Number.isInteger(maxDates) ||
      maxDates < 0)
  ) {
    throw new RangeError("maxDates must be a finite nonnegative integer");
  }

  if (maxDates === 0) return [];

  const { start, end } = normalizeInterval(options?.in, interval);

  let reversed = +start > +end;
  const endTime = reversed ? +start : +end;
  const date = reversed ? end : start;
  date.setHours(0, 0, 0, 0);

  let step = options?.step ?? 1;
  if (!step) return [];
  if (step < 0) {
    step = -step;
    reversed = !reversed;
  }

  const dates: EachDayOfIntervalResult<IntervalType, Options> = [];
  let ringIndex = 0;

  while (+date <= endTime) {
    const currentDate = constructFrom(start, date);
    if (maxDates === undefined || !reversed || dates.length < maxDates) {
      dates.push(currentDate);
    } else {
      dates[ringIndex] = currentDate;
      ringIndex = (ringIndex + 1) % maxDates;
    }

    date.setDate(date.getDate() + step);
    date.setHours(0, 0, 0, 0);

    if (maxDates !== undefined && !reversed && dates.length >= maxDates) {
      break;
    }
  }

  if (reversed) {
    if (
      maxDates !== undefined &&
      dates.length === maxDates &&
      ringIndex !== 0
    ) {
      const oldestDates = dates.splice(0, ringIndex);
      dates.push(...oldestDates);
    }
    dates.reverse();
  }

  return dates;
}

