        ? `.${addLeadingZeros(date_.getMilliseconds(), normalizedFractionDigits)}`
        : "";

    // If there's also date, separate it with time with a space
    const separator = result === "" ? "" : " ";

    // HHmmss or HH:mm:ss.
    result = `${result}${separator}${hour}${timeDelimiter}${minute}${timeDelimiter}${second}${fractionalSecond}`;
  }

  return result;
}
